// ===== מבוא =====
c.push(H1('מבוא'));
c.push(Pind('היום של תלמיד בישראל מתחלק בין שלוש התנהגויות שכל אחת מהן נחקרה בנפרד במשך שנים: זמן מול מסכים, שעות שינה ופעילות גופנית. בשנים האחרונות התגבשה ההבנה שההתנהגויות האלה אינן נפרדות אלא מתחרות על אותן 24 שעות, ושהאיזון ביניהן קשור לבריאות, לרווחה הנפשית ולתפקוד הלימודי (Tremblay et al., 2016). מחקר בקרב 934 תלמידים בבית ספר אוסטרלי מצא ששני אחוזים בלבד עמדו בשלוש ההמלצות יחד, ושעמידה בהמלצת זמן המסך והקפדה על שעות שינה סדירות בסוף השבוע היו קשורות לציונים גבוהים יותר במתמטיקה ובאנגלית (Howie et al., 2020).'));
c.push(Pind('העבודה הנוכחית מפנה את השאלה הזאת לאוכלוסייה שכמעט אינה מופיעה במחקרים האלה: תלמידים עם לקויות למידה. לקות למידה היא הפרעה נוירו-התפתחותית שמתבטאת בקושי מתמשך ברכישת קריאה, כתיבה או חשבון, ושכיחותה בקרב ילדים בגיל בית הספר נאמדת בחמישה עד חמישה עשר אחוזים (American Psychiatric Association [APA], 2022). לתלמידים אלה יש סיבות להיות פגיעים יותר לחוסר איזון בין מסכים, שינה ותנועה. מחקרים מצביעים על שיעורים גבוהים של הפרעות שינה בקרב ילדים עם דיסלקציה ועם לקות למידה ספציפית (Jeffcock & Dimitriou, 2025; Saccani et al., 2022), על קשיים מוטוריים שמלווים את הלקות ומקשים על השתתפות בפעילות גופנית (Blanchet & Assaiante, 2022), ועל קשר בין חשיפה מופרזת למסכים לבין דיווח על לקות למידה בסקרים לאומיים (Qu et al., 2023). עם זאת, כמעט אין מחקר שבדק את שלוש ההתנהגויות יחד באוכלוסייה זו, ובוודאי לא בישראל.'));
c.push(Pind('בישראל השאלה דחופה במיוחד. סקר של איגוד האינטרנט הישראלי מצא שרוב בני הנוער מדווחים על ארבע עד שמונה שעות מסך ביום, ובחברה הערבית השיעור גבוה עוד יותר (איגוד האינטרנט הישראלי, 2022). משרד הבריאות פרסם לאחרונה המלצות חדשות להורים ובהן הגבלת זמן מסך לפי גיל, הרחקת מסכים מחדרי השינה ודחיית הכניסה לרשתות חברתיות, בנימוק שהשימוש במסכים בא על חשבון שינה, פעילות גופנית ולמידה (משרד הבריאות, 2026). אם ההמלצות האלה נכונות לכלל התלמידים, יש מקום לבדוק כיצד הן מתקיימות בקרב תלמידים שהלמידה קשה להם ממילא.'));
c.push(Pind('מטרת המחקר היא לתאר את דפוסי החשיפה למסכים, השינה והפעילות הגופנית בקרב תלמידים עם לקויות למידה בחטיבת הביניים ובחטיבה העליונה, לבחון את הקשרים בין שלוש ההתנהגויות לבין התפקוד הלימודי המדווח, ולהשוות את דפוסי ההתנהגות של תלמידים עם לקויות למידה לאלה של תלמידים ללא לקות. המחקר כמותי ומבוסס על שאלון דיווח עצמי אנונימי.'));
c.push(Pind('העבודה בנויה כך: הפרק הראשון סוקר את הספרות. הוא פותח בהגדרת לקויות למידה ובמאפייניהן, ממשיך לשלוש ההתנהגויות הנחקרות ולמודל המשולב של 24 השעות, מציג את תמונת המצב בישראל ומסתיים ברציונל, במטרות, בשאלות ובהשערות המחקר. הפרק השני מתאר את שיטת המחקר: מערך המחקר, אוכלוסיית המחקר, כלי המחקר, ההליך, דרכי ניתוח הנתונים, השיקולים האתיים ומגבלות המחקר. הפרקים העוסקים בממצאים, בדיון ובסיכום ייכתבו לאחר איסוף הנתונים. גבולות העבודה: היא עוסקת בתלמידים עם לקות למידה מאובחנת בכיתות ז\' עד י"ב, ואינה עוסקת במוגבלות שכלית, באוטיזם או בלקויות חושיות. הפרעת קשב נדונה רק במידה שהיא נלווית ללקות למידה.'));
c.push(BR());

// ===== פרק 1: סקירת ספרות =====
c.push(H1('פרק 1: סקירת ספרות'));

c.push(H2('1.1 לקויות למידה: הגדרה, שכיחות ומאפיינים'));
c.push(Pind('המדריך לאבחון סטטיסטי של הפרעות נפשיות במהדורתו העדכנית מגדיר לקות למידה ספציפית (Specific Learning Disorder) כהפרעה נוירו-התפתחותית שבה קשיים ברכישת מיומנויות אקדמיות, קריאה, כתיבה או חשבון, נמשכים שישה חודשים לפחות למרות התערבות ממוקדת. המיומנויות הפגועות נמוכות באופן ניכר מהמצופה לגיל, הן פוגעות בתפקוד הלימודי או היומיומי, מתחילות בשנות בית הספר, ואינן מוסברות על ידי מוגבלות שכלית, ליקוי חושי, הפרעה נפשית או חסך בהוראה. השכיחות בקרב ילדים בגיל בית הספר נאמדת בחמישה עד חמישה עשר אחוזים (APA, 2022).'));
c.push(Pind('המהדורה החמישית של המדריך הביאה עמה שינוי מושגי. במקום המונח "לקות" (Disability) נבחר המונח "הפרעה" (Disorder), וההגדרה עברה מהסתמכות על פער בין אינטליגנציה להישגים אל דרישה לתיעוד של קושי מתמשך שאינו נענה להתערבות. השינוי הזה מדגיש שהאבחון אינו מסתפק במבחן חד-פעמי אלא מחייב מעקב אחר תגובת התלמיד להוראה (ארן-ארנרייך, 2013). בישראל אימץ משרד החינוך את ההגדרה של המדריך האמריקני כבסיס לאבחון ולמתן התאמות, ואגף לקויות למידה והפרעות קשב בשירות הפסיכולוגי-ייעוצי אחראי על גיבוש המדיניות בתחום (משרד החינוך, ל.ת.). דוח של מרכז המחקר והמידע של הכנסת סקר את הליכי האיתור והאבחון במערכת החינוך והצביע על פערים בין מגזרים ובין שכבות גיל בזמינות האבחון ובמתן ההתאמות (אבגר, 2018).'));
c.push(Pind('לקות למידה אינה מסתכמת בקושי בקריאה או בחשבון. מחקר ישראלי שהשווה תלמידים עם לקויות למידה לתלמידים ללא לקות מצא שתפקודים ניהוליים וידע עולם תורמים להבנת הנקרא בשתי הקבוצות, ושהפער בתפקודים הניהוליים הוא חלק מהתמונה של הלקות (בשארה ווייס, 2025). תפקודים ניהוליים, ובהם ויסות עצמי, תכנון ועיכוב תגובה, הם בדיוק היכולות שנדרשות כדי להפסיק משחק בטלפון וללכת לישון, או כדי לצאת לאימון במקום להישאר על הספה. סקירה שכללה 34 מחקרים משנת 1990 ועד 2022 מצאה שלתלמידים עם לקות למידה ספציפית מיומנויות מוטוריות נמוכות מאלה של בני גילם, ושהפער גדל ככל שהמשימה המוטורית מורכבת יותר וכאשר קיימת תחלואה נלווית. הכותבות קשרו בין הליקויים המוטוריים לבין אורח חיים יושבני (Blanchet & Assaiante, 2022). בנוסף, לקות למידה מופיעה לעיתים קרובות יחד עם הפרעת קשב, ובמצב של תחלואה כפולה מדווחים קשיים בולטים יותר, ובהם הפרעות שינה (Saccani et al., 2022).'));
c.push(Pind('שלושת המאפיינים האלה, קשיים בוויסות עצמי, קשיים מוטוריים ופגיעות לשינה לקויה, הם הרקע לשאלה של העבודה הנוכחית. הם מרמזים שתלמידים עם לקויות למידה עשויים להתקשות יותר מאחרים לשמור על איזון בין מסכים, שינה ותנועה, ושחוסר איזון כזה עלול להעמיק את הקושי הלימודי.'));

c.push(H2('1.2 חשיפה למסכים בקרב ילדים ובני נוער'));
c.push(Pind('ההנחיות הקנדיות לתנועה במהלך 24 שעות, הראשונות שאיחדו את שלוש ההתנהגויות למסמך אחד, ממליצות לילדים ולבני נוער בגילי 5 עד 17 להגביל את זמן המסך לצורכי פנאי לשעתיים ביום לכל היותר (Tremblay et al., 2016). מטא-אנליזה שכללה 387,437 משתתפים מ-23 מדינות מצאה שרוב הילדים ובני הנוער אינם עומדים בשלוש ההמלצות, שאחד מכל חמישה אינו עומד באף אחת מהן, ושהעמידה בהמלצות יורדת בגיל ההתבגרות, במיוחד בקרב בנות (Tapia-Serrano et al., 2022).'));
c.push(Pind('ההשלכות של חשיפה מרובה למסכים נחקרו בעיקר בתחום הבריאות הנפשית. סקירה שיטתית של 50 מחקרים מצאה שהסמארטפון הוא המכשיר הנפוץ ביותר בקרב מתבגרים, ששימוש בו בימי חול קשור לרווחה נפשית נמוכה יותר, ושהשימוש ברשתות חברתיות קשור לסיכון מוגבר לדיכאון בקרב בנות (Santos et al., 2023). ניתוח של סקר לאומי בארצות הברית שכלל 50,231 ילדים ומתבגרים בגילי 6 עד 17 מצא שזמן מסך של ארבע שעות ביום או יותר קשור לסיכון גבוה יותר לחרדה, לדיכאון, לבעיות התנהגות ולהפרעת קשב. הממצא החשוב לעבודה זו הוא שהקשר תווך במידה רבה על ידי שתי ההתנהגויות האחרות: פעילות גופנית הסבירה בין 30.9 ל-38.9 אחוזים מהקשר, שעת שינה לא סדירה הסבירה בין 18.4 ל-23.9 אחוזים, ומשך שינה קצר הסביר עוד כמה אחוזים (Dai & Ouyang, 2026). במילים אחרות, חלק ניכר מהנזק של המסכים עובר דרך מה שהם דוחקים החוצה.'));
c.push(Pind('בנוגע ללקויות למידה עצמן, ניתוח של סקר לאומי אמריקני משנים 2018 עד 2020 מצא שזמן מסך מופרז קשור לדיווח הורים על לקות למידה, על הפרעת קשב, על עיכוב התפתחותי ועל הפרעות שפה, וכי הקשר חזק יותר בקרב בנים ובקרב ילדים בגיל הגן (Qu et al., 2023). המחקר הוא רוחבי ואינו יכול לומר מה קדם למה: ייתכן שילדים שהלמידה קשה להם פונים יותר למסכים, וייתכן שהמסכים מעמיקים את הקושי. מחקר טורקי שהשווה 86 מתבגרים עם הפרעת קשב ולקות למידה ל-86 מתבגרים עם הפרעת קשב בלבד לא מצא הבדל בזמן המסך היומי או בחומרת השימוש הבעייתי, אך מצא שהקבוצה עם לקות הלמידה עסקה במגוון מצומצם יותר של פעילויות מסך והעדיפה פחות משחקי אסטרטגיה ומשחקי חשיבה. המסקנה הייתה שלקות הלמידה מעצבת את אופי השימוש ולא בהכרח את כמותו (Kocabas et al., 2025). סקירה שיטתית ומטא-אנליזה שאספה את המחקרים על היקף זמן המסך בקרב ילדים ובני נוער עם מוגבלויות מגיל לידה ועד 17 מיינה את הנתונים לפי גיל ולפי סוג המוגבלות (Vanderloo et al., 2025). מיפוי כזה ממחיש עד כמה הידע על תלמידים עם לקויות למידה בפרט עדיין דל, ומכאן הצורך במחקרים ממוקדים.'));

c.push(H2('1.3 שינה בגיל בית הספר ובקרב תלמידים עם לקויות למידה'));
c.push(Pind('ההמלצות המקובלות הן תשע עד אחת עשרה שעות שינה בלילה לילדים בגילי 5 עד 13 ושמונה עד עשר שעות למתבגרים בגילי 14 עד 17 (Tremblay et al., 2016). הקשר בין מדיה אלקטרונית לשינה נחקר רבות. סקירה שיטתית של מחקרים ממדינות מערביות בקרב ילדים עד גיל 15 סיכמה שהשימוש במדיה קשור לשעת שינה מאוחרת יותר, למשך שינה קצר יותר ולפגיעה באיכות השינה, ושהקשר נמצא בסוגי מדיה שונים ובשיטות מדידה שונות (Lund et al., 2021). בישראל, מחקר בקרב 470 תלמידי כיתות ח\' ו-ט\' מצא שחשיפה לטלוויזיה ולמחשב, ובעיקר נוכחות של מכשירים בחדר השינה, קשורה לשעת שינה מאוחרת, למשך שינה קצר ולישנוניות ולעייפות בשעות היום (Shochat et al., 2010). המחקר נערך לפני עידן הסמארטפון, ומכאן שממצאיו ככל הנראה ממעיטים בהיקף התופעה כיום.'));
c.push(Pind('שינה חסרה אינה רק עניין של עייפות. מחקר איטלקי שבדק 191 תלמידי בית ספר יסודי באמצעות סוללת מבחנים נוירופסיכולוגית מצא שישנוניות בשעות היום קשורה לתפקוד נמוך יותר במגוון מיומנויות קוגניטיביות ולימודיות, ובהן קריאה, כתיבה, הבנת הנקרא וחשבון (Macchitella et al., 2020). אלה בדיוק התחומים שבהם תלמידים עם לקויות למידה מתקשים ממילא.'));
c.push(Pind('בקרב ילדים עם לקויות למידה הבעיה בולטת יותר. מחקר איטלקי השווה 74 ילדים עם הפרעת קשב, 78 ילדים עם לקות למידה ספציפית ו-76 ילדים עם שתי האבחנות באמצעות סולם הפרעות השינה לילדים. הקבוצה עם התחלואה הכפולה הציגה הפרעות שינה רבות יותר משתי הקבוצות האחרות, בעיקר קשיים בהירדמות ובשמירה על רצף השינה (Saccani et al., 2022). מחקר קהילתי בבריטניה בקרב הורים ל-160 ילדים בגילי 7 עד 13 עם אבחנה ראשית של דיסלקציה מצא ש-66 אחוזים מהילדים הגיעו לרמה קלינית של הפרעות שינה, בעיקר עיכוב בהירדמות, חרדת שינה וישנוניות בשעות היום. רמות החרדה של הילדים לא היו גבוהות מהרגיל ולא הסבירו את העיכוב בהירדמות, ומכאן שהפרעות השינה בדיסלקציה אינן רק תוצר של מצוקה רגשית (Jeffcock & Dimitriou, 2025). שני המחקרים לא מדדו זמן מסך, ולכן אינם יכולים לומר אם השימוש במסכים תורם לקשיי ההירדמות של ילדים אלה. זה אחד הפערים שהעבודה הנוכחית מבקשת למלא.'));

c.push(H2('1.4 פעילות גופנית ותלמידים עם לקויות למידה'));
c.push(Pind('ארגון הבריאות העולמי ממליץ לילדים ולמתבגרים על ממוצע של 60 דקות ביום של פעילות גופנית אירובית בעצימות בינונית עד גבוהה, ועל הגבלת זמן יושבני ובמיוחד זמן מסך לצורכי פנאי. ההמלצה נוסחה במהדורת 2020 כממוצע שבועי ולא כדרישה יומית קשיחה, בעקבות ממצאים שקשרו את התועלת הבריאותית לממוצע היומי (Bull et al., 2020). בישראל, ניתוח של נתוני סקר HBSC בקרב כ-7,000 תלמידי כיתות ו\', ח\' ו-י\' בחינוך הממלכתי, הממלכתי-דתי והממלכתי-ערבי מצא שבנים פעילים גופנית בתדירות גבוהה מבנות, ושגורמים ברמת התלמיד וברמת בית הספר מנבאים יחד את הרגלי הפעילות (בק ואחרים, 2018).'));
c.push(Pind('לתלמידים עם לקויות למידה יש מכשול נוסף בדרך לפעילות גופנית. הסקירה של בלאנשה ואסאיאנטה (Blanchet & Assaiante, 2022) הראתה שקשיים מוטוריים מלווים את הלקות אצל חלק ניכר מהתלמידים, וכי תלמיד שמתקשה בתיאום ובאיזון נוטה להימנע ממשחקי כדור ומספורט תחרותי. ההימנעות מצמצמת את ההתנסות המוטורית, וכך נוצר מעגל של הימנעות ואורח חיים יושבני שמותיר יותר זמן פנוי למסכים.'));
c.push(Pind('לצד זאת, פעילות גופנית היא גם אמצעי התערבות. מטא-אנליזה של מחקרי התערבות בקרב ילדים ומתבגרים עם הפרעות נוירו-התפתחותיות מצאה שתוכניות פעילות גופנית שיפרו את יעילות השינה, את משך השינה ואת רצף השינה כשנמדדו באופן אובייקטיבי. ההשפעה הייתה גדולה יותר בתוכניות שנמשכו יותר מ-12 שבועות, בתדירות של שלוש פעמים בשבוע לפחות ובמפגשים של יותר משעה (Wang et al., 2024). ממצא זה מחבר בין שתי ההתנהגויות: הגברת הפעילות הגופנית עשויה להיות דרך לשפר את השינה של תלמידים עם לקויות למידה, גם בלי להתמודד ישירות עם המסכים.'));

c.push(H2('1.5 המודל המשולב של 24 השעות והקשר לתפקוד הלימודי'));
c.push(Pind('נקודת המוצא התיאורטית של העבודה היא ההנחיות הקנדיות לתנועה במהלך 24 שעות. עד לפרסומן נבחנו פעילות גופנית, התנהגות יושבנית ושינה כל אחת לחוד. ההנחיות המשולבות יצאו מההנחה ששלוש ההתנהגויות מתקיימות באותה יממה, מתחרות זו בזו על הזמן ונוטות להתקבץ יחד, כך ששיפור באחת עשוי לגרור שיפור באחרות (Tremblay et al., 2016). מכאן שגם מחקר על תלמידים עם לקויות למידה צריך למדוד את שלושתן במקביל.'));
c.push(Pind('המחקר של האווי ואחרים (Howie et al., 2020) הוא הבסיס האמפירי המרכזי לעבודה זו ולכן יתואר בפירוט. המחקר נערך בבית ספר אוסטרלי שבו כל תלמיד מביא מכשיר משלו ללמידה, סביבה שבה המסך הוא כלי לימודי ולא רק בידור. 934 תלמידי כיתות ה\' עד י"ב דיווחו על הרגלי השינה, הפעילות הגופנית וההתנהגות היושבנית שלהם, וההישגים הלימודיים נלקחו מרשומות בית הספר. 74 אחוזים מהתלמידים עמדו בהמלצת השינה, 21 אחוזים בהמלצת הפעילות הגופנית ו-15 אחוזים בלבד בהמלצת זמן המסך. שני אחוזים עמדו בשלוש ההמלצות יחד. תלמידים שעמדו בהמלצת זמן המסך קיבלו בממוצע 5.8 נקודות יותר במדד הלימודי הכללי, 7.9 נקודות יותר במתמטיקה ו-3.8 נקודות יותר באנגלית. משך השינה הכולל לא היה קשור לציונים, אך שעת שינה מאוחרת בסוף השבוע הייתה קשורה לירידה של 3.4 נקודות במדד הכללי. תלמידים שעמדו בשתי המלצות לפחות, 23 אחוזים מהמדגם, הציגו הישגים גבוהים יותר בכל המקצועות. הכותבים הסיקו שסדירות השינה חשובה לא פחות מכמותה, ושתוכניות התערבות צריכות לפנות לשלוש ההתנהגויות יחד ולא לאחת מהן בלבד (Howie et al., 2020).'));
c.push(Pind('ממצאים דומים התקבלו במדגמים גדולים ובגילים שונים. בקרב 67,281 ילדים ומתבגרים בסין, עמידה בשלוש ההמלצות הייתה קשורה לסיכוי גבוה יותר להישגים טובים בסינית, במתמטיקה ובאנגלית, ויחסי הסיכויים נעו בין 1.51 ל-1.73. גם כאן, הרכיב שהיה קשור באופן העקבי ביותר להישגים היה העמידה בהמלצת זמן המסך, לבדה או בשילוב עם המלצה אחרת (Chen et al., 2024). מחקר פולני בקרב 114 ילדים בני 8 עד 9 בחן לא ציונים אלא מיומנויות יסוד לקריאה ולכתיבה, ומצא שפעילות גופנית בעצימות בינונית עד גבוהה קשורה לאינטגרציה חזותית-שמיעתית טובה יותר, שאי-עמידה בהמלצת השינה קשורה לאינטגרציה חזותית-שמיעתית נמוכה יותר, ושאי-עמידה בהמלצת זמן המסך קשורה לאינטגרציה תפיסתית-מוטורית נמוכה יותר (Korcz et al., 2023). המיומנויות האלה הן הבסיס לרכישת הקריאה, ולכן הממצא רלוונטי במיוחד ללקויות למידה.'));
c.push(Pind('סיכום הספרות מעלה תמונה עקבית: זמן מסך, שינה ופעילות גופנית קשורים זה לזה ולתפקוד הלימודי, וההשפעה החזקה ביותר על ההישגים מיוחסת לזמן המסך ולסדירות השינה. הפער הוא שכל המחקרים האלה נערכו באוכלוסייה הכללית. אין בהם קבוצה נפרדת של תלמידים עם לקויות למידה, ואין דרך לדעת אם הקשרים חזקים יותר, חלשים יותר או שונים באופיים אצל תלמידים אלה.'));

c.push(H2('1.6 תמונת המצב בישראל'));
c.push(Pind('סקר שערך איגוד האינטרנט הישראלי בקיץ 2022 בקרב בני נוער והורים מצא ש-54 אחוזים מבני הנוער בחברה היהודית החילונית מדווחים על ארבע עד שמונה שעות מסך ביום, ו-11 אחוזים נוספים על יותר משמונה שעות. בחברה הערבית השיעור המדווח על ארבע עד שמונה שעות ביום הגיע ל-67 אחוזים, ובחברה היהודית-דתית הוא היה הנמוך ביותר, 41 אחוזים (איגוד האינטרנט הישראלי, 2022). בספטמבר 2026 פרסם משרד הבריאות המלצות חדשות להורים בליווי קמפיין ציבורי: הימנעות מלאה ממסכים עד גיל שנתיים, עד שעה ביום בגילי שנתיים עד חמש, פחות משעתיים ביום בגילי שש עד תשע, סמארטפון לא לפני גיל 13, רשתות חברתיות לא לפני גיל 15, והרחקת מסכים מחדרי השינה. המשרד נימק את ההמלצות בממצאי סקר HBSC שלפיהם 28.7 אחוזים מתלמידי כיתות ז\' עד י"ב מבלים שש שעות ומעלה מול מסכים מחוץ לשעות הלימודים, ובהשלכות של השימוש על השינה, על הלמידה ועל הבריאות הנפשית (משרד הבריאות, 2026).'));
c.push(Pind('בתחום הפעילות הגופנית, נתוני HBSC מעידים על שיעורי פעילות נמוכים בקרב תלמידי ישראל בהשוואה בינלאומית, עם פערים מובהקים בין בנים לבנות ובין מגזרים (בק ואחרים, 2018). בחברה הערבית בישראל, מחקר שסקר 490 הורים בתקופת הקורונה מצא ירידה בזמן הפעילות הגופנית של הילדים, עלייה בהתנהגות היושבנית ובמשך השינה, וירידה בשיעור הילדים שעמדו בהמלצות לפעילות גופנית ולהתנהגות יושבנית (Ghanamah et al., 2023). המחקר מעיד על כך שדפוסי ההתנהגות רגישים לשינויים סביבתיים, ושכאשר מסגרת בית הספר נחלשת המסכים ממלאים את החלל.'));
c.push(Pind('לעומת שפע הנתונים על כלל התלמידים, לא נמצא בחיפוש הספרות מחקר ישראלי שבדק זמן מסך, שינה ופעילות גופנית בקרב תלמידים עם לקויות למידה. נתוני הרקע קיימים: הדוח של מרכז המחקר והמידע של הכנסת מתאר את היקף האוכלוסייה ואת דרכי האיתור והאבחון (אבגר, 2018), ומחקרים ישראליים בדקו את המאפיינים הקוגניטיביים של תלמידים אלה (בשארה ווייס, 2025). את החוליה שביניהם, ההרגלים היומיומיים, אין.'));

c.push(H2('1.7 רציונל המחקר, מטרת המחקר, שאלות המחקר והשערות המחקר'));
c.push(H3('רציונל המחקר'));
c.push(Pind('הספרות מציגה שלושה קווים שאינם נפגשים. הקו הראשון מראה שזמן מסך, שינה ופעילות גופנית קשורים זה לזה ולהישגים הלימודיים באוכלוסייה הכללית (Chen et al., 2024; Howie et al., 2020; Tremblay et al., 2016). הקו השני מראה שתלמידים עם לקויות למידה סובלים משיעורים גבוהים של הפרעות שינה ומקשיים מוטוריים, ושהם עשויים להשתמש במסכים באופן שונה (Blanchet & Assaiante, 2022; Jeffcock & Dimitriou, 2025; Kocabas et al., 2025; Saccani et al., 2022). הקו השלישי מציג את היקף השימוש במסכים בישראל ואת ההמלצות החדשות (איגוד האינטרנט הישראלי, 2022; משרד הבריאות, 2026). המחקר הנוכחי מחבר את שלושת הקווים ובודק את דפוסי שלוש ההתנהגויות, את הקשרים ביניהן ואת הקשר שלהן לתפקוד הלימודי, בקרב תלמידים עם לקויות למידה בישראל.'));
c.push(H3('מטרת המחקר'));
c.push(P('למחקר שלוש מטרות:'));
c.push(NUM('לתאר את היקף החשיפה למסכים, את משך השינה ואיכותה ואת היקף הפעילות הגופנית בקרב תלמידים עם לקויות למידה, ואת שיעור התלמידים העומדים בהמלצות המקובלות.', 'num1'));
c.push(NUM('לבחון את הקשרים בין שלוש ההתנהגויות לבין עצמן ובינן לבין התפקוד הלימודי המדווח.', 'num1'));
c.push(NUM('להשוות בין תלמידים עם לקויות למידה לבין תלמידים ללא לקויות למידה בדפוסי ההתנהגות ובשיעור העמידה בהמלצות.', 'num1'));
c.push(H3('שאלות המחקר'));
c.push(NUM('מהם דפוסי החשיפה למסכים, השינה והפעילות הגופנית בקרב תלמידים עם לקויות למידה, ואיזה שיעור מהם עומד בכל אחת מההמלצות ובשלושתן יחד?', 'num2'));
c.push(NUM('האם קיים קשר בין היקף החשיפה למסכים לבין משך השינה, שעת השינה והישנוניות בשעות היום בקרב תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיים קשר בין היקף החשיפה למסכים לבין היקף הפעילות הגופנית בקרב תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיים קשר בין החשיפה למסכים, השינה והפעילות הגופנית לבין התפקוד הלימודי המדווח של תלמידים עם לקויות למידה?', 'num2'));
c.push(NUM('האם קיימים הבדלים בין תלמידים עם לקויות למידה לבין תלמידים ללא לקויות למידה בדפוסי ההתנהגות ובשיעור העמידה בהמלצות?', 'num2'));
c.push(H3('השערות המחקר'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין משך השינה, וקשר חיובי בין היקף החשיפה למסכים לבין שעת שינה מאוחרת ובינו לבין ישנוניות בשעות היום (Lund et al., 2021; Shochat et al., 2010).', 'num3'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין היקף הפעילות הגופנית (Dai & Ouyang, 2026; Tremblay et al., 2016).', 'num3'));
c.push(NUM('יימצא קשר שלילי בין היקף החשיפה למסכים לבין התפקוד הלימודי המדווח, וקשר חיובי בין עמידה בהמלצות השינה והפעילות הגופנית לבין התפקוד הלימודי המדווח (Chen et al., 2024; Howie et al., 2020).', 'num3'));
c.push(NUM('תלמידים שעומדים בשתי המלצות לפחות ידווחו על תפקוד לימודי גבוה יותר מתלמידים שעומדים בהמלצה אחת או באף אחת (Howie et al., 2020).', 'num3'));
c.push(NUM('תלמידים עם לקויות למידה ידווחו על משך שינה קצר יותר, על ישנוניות רבה יותר ועל פעילות גופנית מועטה יותר בהשוואה לתלמידים ללא לקויות למידה, ושיעור העומדים בשלוש ההמלצות יחד יהיה נמוך יותר בקרבם (Blanchet & Assaiante, 2022; Jeffcock & Dimitriou, 2025; Saccani et al., 2022).', 'num3'));
c.push(P('לגבי היקף החשיפה למסכים לא מנוסחת השערה מכוונת, מאחר שהמחקר היחיד שהשווה ישירות בין קבוצות לא מצא הבדל בכמות השימוש אלא באופיו (Kocabas et al., 2025). שאלה זו תיבדק כשאלה פתוחה.'));
c.push(BR());

// ===== פרק 2: שיטת המחקר =====
c.push(H1('פרק 2: שיטת המחקר'));
c.push(H2('2.1 מערך המחקר'));
c.push(Pind('המחקר כמותי, במערך רוחבי (חתך) מתאמי-השוואתי. הנתונים נאספים בנקודת זמן אחת באמצעות שאלון דיווח עצמי אנונימי. המערך המתאמי משרת את שאלות המחקר השנייה עד הרביעית, העוסקות בקשרים בין משתנים, והמערך ההשוואתי משרת את השאלה החמישית, העוסקת בהבדלים בין שתי קבוצות. הבחירה במערך רוחבי נובעת ממסגרת הזמן של עבודה סמינריונית ומכך שהמחקר הראשון בתחום באוכלוסייה זו בישראל נועד לתאר ולמפות ולא להוכיח סיבתיות. המערך דומה לזה ששימש במחקרים המרכזיים שנסקרו (Howie et al., 2020; Korcz et al., 2023).'));
c.push(P('משתני המחקר:'));
c.push(BUL('משתנים בלתי תלויים: היקף החשיפה למסכים (שעות ביום בימי חול ובסוף שבוע, ונוכחות מסכים בחדר השינה); משך השינה ושעת השינה; היקף הפעילות הגופנית.'));
c.push(BUL('משתנים תלויים: ישנוניות בשעות היום; תפקוד לימודי מדווח (ממוצע ציונים מדווח ותפקוד יומי בלמידה).'));
c.push(BUL('משתנה קבוצתי: קיום אבחנה של לקות למידה (קבוצת המחקר) לעומת היעדר אבחנה (קבוצת ההשוואה).'));
c.push(BUL('משתני רקע: מין, גיל, כיתה, מגזר, אבחנה נלווית של הפרעת קשב, נטילת טיפול תרופתי.'));

c.push(H2('2.2 אוכלוסיית המחקר והמדגם'));
c.push(Pind('אוכלוסיית המחקר היא תלמידי כיתות ז\' עד י"ב במערכת החינוך בישראל. קבוצת המחקר כוללת תלמידים בעלי אבחון תקף של לקות למידה (אבחון דידקטי או פסיכו-דידקטי) המקבלים התאמות בלמידה או בבחינות. קבוצת ההשוואה כוללת תלמידים מאותן שכבות גיל ללא אבחון של לקות למידה. גודל המדגם המתוכנן הוא 120 תלמידים: 60 בקבוצת המחקר ו-60 בקבוצת ההשוואה, בטווח הגילים 12 עד 18. חישוב מקדים באמצעות מחשבון עוצמה סטטיסטית מראה שמדגם של 60 בכל קבוצה מאפשר לזהות הבדל בגודל אפקט בינוני (d = 0.5) בעוצמה של כ-77 אחוזים ברמת מובהקות של 5 אחוזים, ומדגם של 60 בקבוצת המחקר מאפשר לזהות מתאם בינוני (r = 0.35) בעוצמה דומה. אם קבוצת ההשוואה לא תגויס במלואה, השערות המחקר הראשונה עד הרביעית ניתנות לבדיקה בקבוצת המחקר בלבד.'));
c.push(Pind('הדגימה היא דגימת נוחות. התלמידים יגויסו בשניים עד שלושה בתי ספר על-יסודיים שבהם פועל מרכז תמיכה או רכז לקויות למידה, באמצעות פנייה למנהלים וליועצות. קבוצת ההשוואה תגויס מאותם בתי ספר ומאותן שכבות גיל, כדי לצמצם הבדלים סביבתיים בין הקבוצות. קריטריוני הכללה לקבוצת המחקר: אבחון לקות למידה שתועד בבית הספר, גיל 12 עד 18, שליטה בשפת השאלון. קריטריוני אי-הכללה לשתי הקבוצות: מוגבלות שכלית, אבחנה של אוטיזם, לקות חושית שאינה מתוקנת, או מחלה כרונית שמגבילה פעילות גופנית. תלמידים עם הפרעת קשב נלווית ייכללו בקבוצת המחקר, ומשתנה זה יירשם ויבוקר בניתוח, בהתאם לממצאים על תחלואה כפולה (Saccani et al., 2022).'));

c.push(H2('2.3 כלי המחקר'));
c.push(Pind('כלי המחקר הוא שאלון סגור לדיווח עצמי שמורכב מחמישה חלקים. השאלון המלא מובא בנספח א\'. משך המילוי המשוער הוא 15 עד 20 דקות.'));
c.push(H3('חלק א: שאלון פרטים אישיים'));
c.push(P('שאלון שחובר לצורך המחקר וכולל מין, גיל, כיתה, מגזר, קיום אבחון של לקות למידה וסוגו, קיום אבחנה של הפרעת קשב, ונטילת טיפול תרופתי. השאלון אינו מבקש פרטים מזהים.'));
c.push(H3('חלק ב: שאלון חשיפה למסכים'));
c.push(P('שאלון שחובר לצורך המחקר על בסיס הפריטים ששימשו במחקר האוסטרלי (Howie et al., 2020) ובסקר HBSC בישראל (בק ואחרים, 2018). הנבדק מדווח על מספר השעות ביום מוקדשות לכל סוג פעילות מסך בנפרד, בימי חול ובסוף השבוע: צפייה בטלוויזיה ובסרטונים, משחקי מחשב וטלפון, רשתות חברתיות ושיחות, ושימוש במסך לצורכי לימודים. הפריטים מאפשרים לחשב זמן מסך פנאי כולל ולהבחין בינו לבין שימוש לימודי. פריטים נוספים בודקים נוכחות של טלפון או מסך אחר בחדר השינה, שימוש במסך בחצי השעה שלפני השינה ומספר ההתעוררויות בלילה בגלל הטלפון. עמידה בהמלצה מוגדרת כזמן מסך פנאי של עד שעתיים ביום בממוצע (Tremblay et al., 2016).'));
c.push(H3('חלק ג: שאלון הרגלי שינה וישנוניות'));
c.push(P('החלק כולל שני רכיבים. הרכיב הראשון הוא פריטי הרגלי שינה: שעת השינה ושעת הקימה בימי חול ובסוף השבוע, שמהן מחושבים משך השינה והפער בין ימי חול לסוף השבוע (Howie et al., 2020; Shochat et al., 2010). עמידה בהמלצה מוגדרת כתשע עד אחת עשרה שעות שינה לגיל 13 ומטה ושמונה עד עשר שעות לגיל 14 ומעלה (Tremblay et al., 2016). הרכיב השני הוא סולם הישנוניות היומית לילדים (Pediatric Daytime Sleepiness Scale), שפותח ותוקף בקרב תלמידי חטיבת ביניים ונמצא קשור להישגים לימודיים (Drake et al., 2003). הסולם כולל שמונה פריטים על ישנוניות במצבים שונים במהלך היום, בסולם של חמש דרגות מ-0 (אף פעם) עד 4 (תמיד). ציון הסולם הוא סכום הפריטים, בטווח 0 עד 32, וציון גבוה מעיד על ישנוניות רבה יותר. במחקר המקורי דווחה מהימנות פנימית של 0.80 (Drake et al., 2003). הסולם תורגם לעברית לצורך המחקר בתרגום ובתרגום חוזר, ומהימנותו תחושב על נתוני המדגם הנוכחי.'));
c.push(H3('חלק ד: שאלון פעילות גופנית'));
c.push(P('שאלון הפעילות הגופנית למתבגרים (Physical Activity Questionnaire for Adolescents, PAQ-A) הוא שאלון דיווח עצמי שמודד את רמת הפעילות הגופנית בשבעת הימים האחרונים בקרב בני 14 עד 19, ולו גרסה מקבילה לילדים בני 8 עד 14 (Kowalski et al., 2004). השאלון כולל שמונה פריטים: רשימת פעילויות ספורט ותדירותן, פעילות בשיעורי חינוך גופני, בהפסקות, אחרי בית הספר, בערבים, בסוף השבוע, ותיאור כללי של השבוע. הציון הכולל הוא ממוצע הפריטים בטווח 1 עד 5, וציון גבוה מעיד על פעילות רבה יותר. לשאלון נוסף פריט HBSC שבודק את מספר הימים בשבוע האחרון שבהם התלמיד היה פעיל 60 דקות לפחות, ופריט זה משמש להגדרת העמידה בהמלצה של 60 דקות ביום (Bull et al., 2020).'));
c.push(H3('חלק ה: שאלון תפקוד לימודי מדווח'));
c.push(P('שאלון שחובר לצורך המחקר. הוא כולל דיווח על ממוצע הציונים בתעודה האחרונה ועל הציון האחרון במתמטיקה ובאנגלית, שני המקצועות שנמצאו רגישים ביותר לזמן מסך במחקר האוסטרלי (Howie et al., 2020). בנוסף, חמישה פריטים בסולם של חמש דרגות בודקים תפקוד יומי בלמידה: ריכוז בשיעורים, הכנת שיעורי בית, איחורים, הרגשה של עייפות בשיעורים ותחושת מסוגלות בלמידה. ציון התפקוד היומי הוא ממוצע הפריטים. הבחירה בדיווח עצמי על ציונים, ולא בציונים מרשומות בית הספר, נובעת מהצורך לשמור על אנונימיות מלאה של תלמידים מאוכלוסייה רגישה.'));

c.push(H2('2.4 הליך המחקר'));
c.push(Pind('בשלב הראשון תוגש בקשה לאישור המחקר לוועדת האתיקה של המוסד ולמנחה. במקביל תיערך פנייה למנהלי בתי הספר לקבלת הסכמתם ולזיהוי רכז לקויות הלמידה או היועצת שילוו את איסוף הנתונים. בשלב השני יועברו להורי התלמידים טופסי הסכמה מדעת, שבהם יוסבר נושא המחקר, אופי השאלון, האנונימיות והזכות לסרב או להפסיק בכל שלב. בשלב השלישי יועבר השאלון לתלמידים שהוריהם הסכימו, במסגרת שיעור או שעת חינוך, בנוכחות החוקרת ואיש צוות. השאלון יועבר על גבי טופס מקוון או בדפוס, לפי אפשרויות בית הספר. לתלמידים עם לקויות למידה יוצע להקריא את השאלות בקול או להאריך את זמן המילוי, כדי שהקושי בקריאה לא ישפיע על איכות הדיווח. לפני ההעברה הרחבה ייערך מחקר חלוץ בקרב עשרה תלמידים לבדיקת בהירות הניסוח ומשך המילוי, והשאלון יתוקן לפי הצורך. איסוף הנתונים מתוכנן לתקופה של שישה עד שמונה שבועות במהלך סמסטר לימודים רגיל, ולא בתקופת חופשות או בחינות.'));

c.push(H2('2.5 ניתוח הנתונים'));
c.push(Pind('הנתונים ינותחו בתוכנת SPSS. תחילה יחושבו סטטיסטיקה תיאורית (ממוצעים, סטיות תקן, שכיחויות ואחוזים) לכל משתני המחקר ולשיעור העמידה בכל המלצה ובשלושתן יחד, בנפרד לכל קבוצה. מהימנות הסולמות תיבדק באמצעות אלפא של קרונבך. השערות המחקר הראשונה עד השלישית ייבדקו באמצעות מתאמי פירסון בין המשתנים הרציפים, וכאשר ההתפלגות אינה נורמלית באמצעות מתאם ספירמן. ההשערה הרביעית תיבדק באמצעות ניתוח שונות חד-כיווני להשוואת התפקוד הלימודי בין תלמידים העומדים באפס, באחת, בשתיים או בשלוש המלצות. ההשערה החמישית תיבדק באמצעות מבחני t למדגמים בלתי תלויים להשוואת ממוצעים ומבחני חי בריבוע להשוואת שיעורי העמידה בהמלצות בין הקבוצות. לבסוף תיערך רגרסיה לינארית מרובה שבה התפקוד הלימודי המדווח הוא המשתנה התלוי, ושלוש ההתנהגויות, לצד משתני הרקע והקבוצה, הן המנבאים, כדי לבחון את התרומה הייחודית של כל התנהגות. רמת המובהקות שתאומץ היא 5 אחוזים.'));

c.push(H2('2.6 שיקולים אתיים'));
c.push(Pind('המחקר עוסק בקטינים מאוכלוסייה רגישה ולכן נדרשת הקפדה יתרה. השתתפות מותנית בהסכמה בכתב של ההורים ובהסכמה של התלמיד עצמו, והתלמיד רשאי להפסיק בכל שלב בלי הסבר ובלי שייפגע. השאלון אנונימי לחלוטין: אין בו שם, מספר זהות או פרט מזהה אחר, והשיוך לקבוצת המחקר נעשה על סמך דיווח עצמי ולא על סמך רשימות של בית הספר. השאלונים המודפסים יישמרו במקום נעול והקבצים המקוונים יישמרו בקובץ מוגן בסיסמה, והם יושמדו בתום העבודה. במהלך ההעברה תוסבר לתלמידים מטרת המחקר בשפה מותאמת, ותודגש העובדה שאין תשובות נכונות ולא נכונות. סוגיה ייחודית לאוכלוסייה זו היא הרגישות של תלמידים לסימון כ"מאובחנים" בפני חבריהם. לכן השאלון יועבר לכל תלמידי הכיתה יחד, ללא הפרדה בין הקבוצות, והשיוך ייקבע רק בניתוח. המחקר לא יבוצע לפני קבלת אישור ועדת האתיקה המוסדית ואישור מנהלי בתי הספר.'));

c.push(H2('2.7 מגבלות המחקר'));
c.push(Pind('למחקר כמה מגבלות שיש להביא בחשבון בפירוש הממצאים. ראשית, המערך רוחבי, ולכן הוא יכול להצביע על קשרים אך לא על כיוון סיבתי: אין דרך לדעת אם המסכים פוגעים בשינה או אם תלמידים שמתקשים להירדם פונים למסך. שנית, כל המשתנים נמדדים בדיווח עצמי, ודיווח על זמן מסך ועל ציונים חשוף להטיות של זיכרון ושל רצייה חברתית. מדידה אובייקטיבית באמצעות אפליקציות מעקב או מד תאוצה לא הייתה אפשרית במסגרת העבודה. שלישית, הדגימה היא דגימת נוחות במספר קטן של בתי ספר, ולכן ההכללה לכלל התלמידים עם לקויות למידה בישראל מוגבלת. רביעית, קבוצת התלמידים עם לקויות למידה אינה אחידה: היא כוללת סוגי לקות שונים ותלמידים עם הפרעת קשב נלווית ובלעדיה, וגודל המדגם אינו מאפשר ניתוח נפרד לכל תת-קבוצה. חמישית, השאלונים המקוריים לישנוניות ולפעילות גופנית פותחו באנגלית, ותרגומם לעברית לצורך המחקר לא עבר תיקוף מלא. למרות המגבלות, המחקר מספק תיאור ראשון של שלוש ההתנהגויות יחד בקרב תלמידים עם לקויות למידה בישראל, ויכול לשמש בסיס למחקרי המשך במערך אורך ובמדידה אובייקטיבית.'));
c.push(BR());

